#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <sstream>
#include "attention_runtime.h"

namespace fs = std::filesystem; using namespace attention_dispatcher;
struct Stats { double mean=0,min=0,max=0; };
static Stats stats(const std::vector<double>& v) { Stats s; if (v.empty()) return s; s.min=*std::min_element(v.begin(),v.end()); s.max=*std::max_element(v.begin(),v.end()); s.mean=std::accumulate(v.begin(),v.end(),0.0)/v.size(); return s; }
static bool read_f32(const fs::path& p,std::vector<float>& v,std::size_t n){std::ifstream f(p,std::ios::binary);if(!f)return false;v.resize(n);f.read(reinterpret_cast<char*>(v.data()),static_cast<std::streamsize>(n*sizeof(float)));return f.gcount()==static_cast<std::streamsize>(n*sizeof(float));}
static void json_stats(std::ostream& o,const Stats&s){o<<"{\"mean\":"<<s.mean<<",\"min\":"<<s.min<<",\"max\":"<<s.max<<'}';}
struct Case { const char* label; AttentionRequest request; const char* core; };
int main(int argc,char**argv){
 if(argc!=2){std::cerr<<"usage: runtime_validation <artifact_root>\n";return 2;} fs::path root=fs::absolute(argv[1]); const std::string root_json=root.generic_string(); ArtifactRegistry registry;std::string error;if(!registry.scan(root,error)){std::cerr<<error<<'\n';return 3;} NcnnModelCache cache;
 const Case cases[]={{"Case A",{1,4,16,16,32,"fp32"},"core_444_grid_1x4x4"},{"Case B",{1,3,16,16,32,"fp32"},"core_344_grid_1x4x4"},{"Case C",{1,4,17,17,32,"fp32"},"core_444_grid_1x5x5"},{"Case D",{1,8,32,32,32,"fp32"},"core_444_grid_2x8x8"},{"Case E",{1,5,19,21,32,"fp32"},"core_444_grid_2x5x6"}};
 struct Record { const Case* c; RuntimeResult r; bool pass=false; float max=0; double mean=0;std::size_t nan=0,inf=0;Stats metadata,lookup,partition,mask,infer,reverse,total;}; std::vector<Record> records;
 for(const auto& c:cases){Record rec;rec.c=&c; Metadata m{};const CoreInfo* core=nullptr; if(!dispatch_request(c.request,registry,m,core,error)){rec.r.error_message=error;records.push_back(std::move(rec));continue;}const std::size_t count=static_cast<std::size_t>(c.request.batch)*c.request.time*c.request.height*c.request.width*c.request.channels;std::vector<float> input,reference;if(!read_f32(core->directory/"reference_input.bin",input,count)||!read_f32(core->directory/"reference_output.bin",reference,count)){rec.r.error_message="reference read failed";records.push_back(std::move(rec));continue;}rec.r=run_attention(c.request,input,registry,cache);if(rec.r.success){double sum=0;for(size_t i=0;i<count;++i){if(std::isnan(rec.r.output[i]))++rec.nan;if(std::isinf(rec.r.output[i]))++rec.inf;float d=std::fabs(rec.r.output[i]-reference[i]);rec.max=std::max(rec.max,d);sum+=d;}rec.mean=sum/count;rec.pass=rec.r.selected_core==c.core&&rec.r.output.size()==count&&rec.max<1e-4f&&rec.nan==0&&rec.inf==0;}
 std::vector<double>a,b,d,e,f,g,h;for(int warm=0;warm<3;++warm)run_attention(c.request,input,registry,cache);for(int i=0;i<10;++i){auto x=run_attention(c.request,input,registry,cache);if(!x.success){rec.pass=false;rec.r.error_message=x.error_message;break;}a.push_back(x.metadata_ms);b.push_back(x.registry_lookup_ms);d.push_back(x.partition_ms);e.push_back(x.mask_generation_ms);f.push_back(x.ncnn_inference_ms);g.push_back(x.reverse_crop_ms);h.push_back(x.total_runtime_ms);}rec.metadata=stats(a);rec.lookup=stats(b);rec.partition=stats(d);rec.mask=stats(e);rec.infer=stats(f);rec.reverse=stats(g);rec.total=stats(h);records.push_back(std::move(rec));}
 RuntimeResult negative=run_attention({1,4,99,99,32,"fp32"},std::vector<float>(static_cast<size_t>(4)*99*99*32),registry,cache); const bool negative_pass=!negative.success&&negative.selected_core.empty(); bool all=negative_pass;for(const auto&r:records)all=all&&r.pass;
 fs::create_directories("reports");std::ofstream j("reports/runtime_validation.json");j<<std::setprecision(10)<<"{\n\"environment\":{\"backend\":\"ncnn-cpu\",\"dtype\":\"fp32\",\"build_type\":\"Release\",\"benchmark_iterations\":10,\"ncnn_threads\":1},\n\"registry\":{\"artifact_root\":\""<<root_json<<"\",\"discovered_core_count\":"<<registry.size()<<",\"cache_size_after_validation\":"<<cache.size()<<"},\n\"cases\":[\n";for(size_t i=0;i<records.size();++i){const auto&r=records[i];const auto&q=r.c->request;j<<"{\"name\":\""<<r.c->label<<"\",\"input_shape\":["<<q.batch<<','<<q.time<<','<<q.height<<','<<q.width<<','<<q.channels<<"],\"window\":["<<r.r.metadata.window_t<<','<<r.r.metadata.window_h<<','<<r.r.metadata.window_w<<"],\"grid\":["<<r.r.metadata.grid_t<<','<<r.r.metadata.grid_h<<','<<r.r.metadata.grid_w<<"],\"selected_core\":\""<<r.r.selected_core<<"\",\"expected_core\":\""<<r.c->core<<"\",\"extract_status\":\""<<(r.r.success?"PASS":"FAIL")<<"\",\"max_abs_error\":"<<r.max<<",\"mean_abs_error\":"<<r.mean<<",\"nan_count\":"<<r.nan<<",\"inf_count\":"<<r.inf<<",\"model_load_ms\":"<<r.r.model_load_ms<<",\"latency_ms\":{\"metadata\":";json_stats(j,r.metadata);j<<",\"registry_lookup\":";json_stats(j,r.lookup);j<<",\"partition\":";json_stats(j,r.partition);j<<",\"mask_generation\":";json_stats(j,r.mask);j<<",\"ncnn_inference\":";json_stats(j,r.infer);j<<",\"reverse_crop\":";json_stats(j,r.reverse);j<<",\"total_runtime\":";json_stats(j,r.total);j<<"},\"error_message\":\""<<r.r.error_message<<"\"}"<<(i+1<records.size()?",\n":"\n");}j<<"],\n\"negative_cases\":[{\"input_shape\":[1,4,99,99,32],\"success\":"<<(negative.success?"true":"false")<<",\"selected_core\":\""<<negative.selected_core<<"\",\"error_message\":\""<<negative.error_message<<"\"}],\n\"overall_status\":\""<<(all?"PASS":"PARTIAL")<<"\"\n}\n";
 fs::create_directories("docs");std::ofstream md("docs/runtime-validation-report.md");md<<"# Adaptive Window Runtime Validation\n\n## Scope\nRelease ncnn CPU FP32 validation of five static profiles.\n\n## Runtime Architecture\nArtifactRegistry → dispatcher → model cache → host partition/mask → ncnn → reverse/crop.\n\n## Artifact Registry\nDiscovered "<<registry.size()<<" cores under `"<<root.string()<<"`.\n\n## Model Cache\nLoaded "<<cache.size()<<" models; steady-state benchmark excludes first-load time.\n\n## Five-Case Matrix\n\n| Case | Core | Extract | Max error | Mean error |\n|---|---|---|---:|---:|\n";for(const auto&r:records)md<<'|'<<r.c->label<<'|'<<r.r.selected_core<<'|'<<(r.r.success?"PASS":"FAIL")<<'|'<<r.max<<'|'<<r.mean<<"|\n";md<<"\n## Performance Baseline\nCPU FP32, ncnn threads=1, three warmups and ten cached runs per case. See `reports/runtime_validation.json` for per-stage mean/min/max.\n\n## Negative Shape Handling\n`[1,4,99,99,32]`: "<<(negative_pass?"safely rejected.":"unexpected result.")<<"\n\n## Known Build Constraint\nDebug runner cannot link Release ncnn CRT; validation uses a separate Release build.\n\n## Current Limitations\nOnly five static profiles are supported. Arbitrary resolutions, RoPE, Q/K Norm, text conditioning, varlen attention, Vulkan, and SeedVR2 weights are not implemented.\n\n## Phase 6.3 Status\n"<<(all?"READY":"PARTIAL")<<"\n\n## Next Recommended Milestone\nIntegrate the cached static-core runtime into the broader SeedVR2 pipeline.\n";
 std::cout<<"runtime_validation="<<(all?"PASS":"PARTIAL")<<" cases="<<records.size()<<" cache_size="<<cache.size()<<'\n';for(const auto&r:records)std::cout<<r.c->label<<" core="<<r.r.selected_core<<" extract="<<(r.r.success?"PASS":"FAIL")<<" max="<<r.max<<" mean="<<r.mean<<'\n';return all?0:4;
}
